// @generated by project-forge — visual-render-panels.mjs (blueprint, catalog, focus card, quick-look, cmdk & dialogs)
import { escapeHtml, escapeXml, sanitizeSafeHref, sanitizeSafeImgSrc, toRelPath } from './visual-layout.mjs'

export const MAX_PROTOTYPE_SRCDOC_BYTES = 512 * 1024

const DIFF_LABELS = { added: '新增', modified: '修改', removed: '拟移除', impacted: '受波及' }

function renderListItems(items) {
  return `<ul class="pf-brief-list">${items.map((x) => `<li>${escapeHtml(x)}</li>`).join('')}</ul>`
}

function collectDownstreamImpacted(rootId, adj, nodeById) {
  const out = []
  const seen = new Set([rootId])
  const queue = [rootId]
  while (queue.length > 0) {
    const cur = queue.shift()
    for (const nxtId of adj.get(cur) || []) {
      if (seen.has(nxtId)) continue
      seen.add(nxtId)
      const node = nodeById.get(nxtId)
      if (node && node.diffState === 'impacted') out.push(node)
      queue.push(nxtId)
    }
  }
  return out
}

function buildRootChangeEntries(nodes = [], edges = []) {
  const nodeById = new Map(nodes.map((n) => [n.id, n]))
  const adj = new Map()
  for (const e of edges) {
    if (!adj.has(e.fromId)) adj.set(e.fromId, [])
    adj.get(e.fromId).push(e.toId)
  }
  const order = { added: 0, modified: 1, removed: 2 }
  const roots = nodes
    .filter((n) => n.diffState === 'added' || n.diffState === 'modified' || n.diffState === 'removed')
    .sort((a, b) => (order[a.diffState] - order[b.diffState]) || a.id.localeCompare(b.id))

  const nestedIds = new Set()
  const entries = roots.map((n) => {
    const downstream = collectDownstreamImpacted(n.id, adj, nodeById)
    for (const d of downstream) nestedIds.add(d.id)
    return { item: n, downstream }
  })
  const orphanImpacted = nodes.filter((n) => n.diffState === 'impacted' && !nestedIds.has(n.id))
  for (const imp of orphanImpacted) entries.push({ item: imp, downstream: [] })
  return entries
}

function renderChangeCardHtml({ item, downstream = [] }) {
  const st = item.diffState || 'modified'
  const label = DIFF_LABELS[st] || st
  const d = item.changeDetail || {}
  let detailHtml = ''
  if (d.before && d.after) {
    detailHtml = `<div class="pf-ba-row"><span class="pf-ba-old">${escapeHtml(d.before)}</span><span class="pf-ba-arr">→</span><span class="pf-ba-new">${escapeHtml(d.after)}</span></div>`
  } else if (d.reason) {
    const rep = d.replacementId
      ? ` · 替代：<button type="button" class="pf-chip-btn pf-chip-inline" data-target-id="${escapeXml(d.replacementId)}">${escapeHtml(d.replacementId)}</button>`
      : ''
    detailHtml = `<p class="pf-chg-note">${escapeHtml(d.reason)}${rep}</p>`
  } else if (d.note) {
    detailHtml = `<p class="pf-chg-note">${escapeHtml(d.note)}</p>`
  } else if (Array.isArray(item.impactReasons) && item.impactReasons.length > 0) {
    detailHtml = `<p class="pf-chg-note">${escapeHtml(item.impactReasons.join('；'))}</p>`
  } else if (item.summary || item.description) {
    detailHtml = `<p class="pf-chg-note">${escapeHtml(item.summary || item.description)}</p>`
  }
  const titleCls = st === 'removed' ? ' class="pf-node-title-removed"' : ''
  const nestedHtml = downstream.length > 0
    ? `<div class="pf-impact-nest"><span class="pf-impact-lbl">波及下游 (${downstream.length})</span><div class="pf-chip-row">${downstream.map((imp) => `<button type="button" class="pf-chip-btn" data-target-id="${escapeXml(imp.id)}">${escapeHtml(imp.title)}</button>`).join('')}</div></div>`
    : ''
  return `<div class="pf-chg-card pf-chg-${escapeXml(st)}"><button type="button" class="pf-chg-main" data-target-id="${escapeXml(item.id)}"><div class="pf-chg-head"><strong${titleCls}>${escapeHtml(item.title)}</strong><span class="pf-pill pf-pill-${escapeXml(st)}">${escapeXml(label)}</span></div><span class="pf-muted-note">${escapeHtml(item.domainTitle || item.domain)}</span>${detailHtml}</button>${nestedHtml}</div>`
}

export function renderBlueprintLandingHtml(model, verdict, verdictLabel) {
  const bd = model?.briefData
  const counts = model?.overlayCounts || { added: 0, modified: 0, removed: 0, impacted: 0 }
  const treeNodes = model?.tree?.nodes || []
  const treeEdges = model?.tree?.edges || []
  let entries = buildRootChangeEntries(treeNodes, treeEdges)
  if (entries.length === 0 && bd?.changeGroups) {
    const cg = bd.changeGroups
    const fallback = [...(cg.added || []), ...(cg.modified || []), ...(cg.removed || []), ...(cg.impacted || [])]
    entries = fallback.map((item) => ({ item, downstream: [] }))
  }

  const countersHtml = [
    ['added', '新增模块', counts.added || 0],
    ['modified', '修改模块', counts.modified || 0],
    ['removed', '拟移除', counts.removed || 0],
    ['impacted', '受波及下游', counts.impacted || 0],
  ].map(([st, lbl, num]) => `<div class="pf-stat-box"><span class="pf-stat-num">${num}</span><span class="pf-stat-lbl">${lbl}</span></div>`).join('')

  const changesHtml = entries.length > 0
    ? `<div class="pf-chg-grid">${entries.map(renderChangeCardHtml).join('')}</div>`
    : '<div class="pf-empty-box">当前尚未标记四态变更模块，可通过 --affected-feature / --add-feature / --remove-feature 标注。</div>'

  if (!bd) {
    return `<div class="pf-scroll-panel"><div class="pf-verdict-hero"><span class="pf-verdict-pill" data-tone="${escapeHtml(verdict.tone || 'pass')}">${verdictLabel}</span><p class="pf-verdict-copy">${escapeHtml(verdict.summary || '')}</p></div><div class="pf-stat-row">${countersHtml}</div>${changesHtml}</div>`
  }

  const slices = (bd.childSlices || []).map((s) => `${s.key}：${s.rel}（${s.status}${s.done ? '，已完成' : ''}）`)
  const masterItems = bd.masterPrd
    ? [`总控 PRD：${bd.masterPrd.rel}（${bd.masterPrd.status}，${bd.masterPrd.approved ? '已批准' : '未批准'}）`, ...slices]
    : slices
  const wtItems = (bd.activeWorktrees || []).map((w) => `工作树 ${w.taskId} [${w.status}] ${w.branch || ''}`.trim())
  const sliceAndWt = [...masterItems, ...wtItems]
  const openItems = [...(bd.mergedOpen || []), ...(bd.pendingDecisions || []).map((p) => `${p.file}:${p.line} ${p.text}`)]

  const briefCards = []
  if ((bd.goals?.length || 0) > 0 || (bd.nonGoals?.length || 0) > 0) {
    briefCards.push([
      '<section class="pf-brief-card"><h3>核心目标与不做边界</h3>',
      bd.goals?.length > 0 ? `<span class="pf-inspector-label">目标</span>${renderListItems(bd.goals)}` : '',
      bd.nonGoals?.length > 0 ? `<span class="pf-inspector-label">不做边界</span>${renderListItems(bd.nonGoals)}` : '',
      '</section>',
    ].filter(Boolean).join(''))
  }
  if ((bd.flowDeltas?.length || 0) > 0 || sliceAndWt.length > 0) {
    briefCards.push([
      '<section class="pf-brief-card"><h3>流程变化与 1:N 切片</h3>',
      bd.flowDeltas?.length > 0 ? `<span class="pf-inspector-label">流程增量</span>${renderListItems(bd.flowDeltas)}` : '',
      sliceAndWt.length > 0 ? `<span class="pf-inspector-label">切片与工作树</span>${renderListItems(sliceAndWt)}` : '',
      '</section>',
    ].filter(Boolean).join(''))
  }
  if ((bd.mergedDecisions?.length || 0) > 0) {
    briefCards.push(`<section class="pf-brief-card"><h3>已拍板决策</h3>${renderListItems(bd.mergedDecisions)}</section>`)
  }
  if (openItems.length > 0) {
    briefCards.push(`<section class="pf-brief-card"><h3>待确认问题</h3>${renderListItems(openItems)}</section>`)
  }

  return [
    '<div class="pf-scroll-panel">',
    `<div class="pf-verdict-hero"><span class="pf-verdict-pill" data-tone="${escapeHtml(verdict.tone || 'pass')}">${verdictLabel}</span><p class="pf-verdict-copy">${escapeHtml(bd.verdict || verdict.summary || '')}</p></div>`,
    `<div class="pf-stat-row">${countersHtml}</div>`,
    `<section class="pf-bp-sec"><h3 class="pf-bp-h">四态变更清单（点击定位模块）</h3>${changesHtml}</section>`,
    briefCards.length > 0 ? `<div class="pf-brief-grid">${briefCards.join('')}</div>` : '',
    '</div>',
  ].filter(Boolean).join('\n')
}

export function renderCatalogHtml(tree) {
  const nodes = tree?.nodes || []
  const domains = tree?.domains || []
  if (nodes.length === 0) return '<div class="pf-empty-box">暂无已映射模块。</div>'
  const byDom = new Map()
  for (const d of domains) byDom.set(d.id, { dom: d, items: [] })
  for (const n of nodes) {
    if (!byDom.has(n.domain)) byDom.set(n.domain, { dom: { id: n.domain, title: n.domainTitle || n.domain }, items: [] })
    byDom.get(n.domain).items.push(n)
  }
  return Array.from(byDom.values()).filter((g) => g.items.length > 0).map((g) => {
    const itemsHtml = g.items.map((n) => {
      const diffText = DIFF_LABELS[n.diffState] || ''
      const badge = diffText ? `<span class="pf-pill pf-pill-${escapeXml(n.diffState)}">${escapeXml(diffText)}</span>` : ''
      const sub = n.shortSummary || toRelPath(n.primaryAnchor || n.entrypoints?.[0] || n.modules?.[0] || '') || n.id
      return `<button type="button" class="pf-catalog-item" data-target-id="${escapeXml(n.id)}"><div class="pf-catalog-head"><span>${escapeHtml(n.title)}</span>${badge}</div><span class="pf-catalog-paths">${escapeHtml(sub)}</span></button>`
    }).join('')
    return `<section class="pf-catalog-group" data-domain-group="${escapeXml(g.dom.id)}"><div class="pf-catalog-dom"><span>${escapeHtml(g.dom.title)}</span><span>${g.items.length}</span></div>${itemsHtml}</section>`
  }).join('\n')
}

export function renderDiffRowsHtml(nodes, edges = []) {
  const entries = buildRootChangeEntries(nodes || [], edges || [])
  if (entries.length === 0) return '<div class="pf-empty-box">当前无活跃变更，所有模块均处于已同步状态。</div>'
  return entries.map(renderChangeCardHtml).join('\n')
}

